{"id":"956f0278-303b-4df8-96ca-422b7d317db6","slug":"create-payment-intent","name":"create-payment-intent","status":"ACTIVE","version":19,"created_at":1772475247137,"updated_at":1776576706478,"verify_jwt":false,"import_map":false,"entrypoint_path":"/tmp/user_fn_vtybccqqbyjbmhkpliyn_956f0278-303b-4df8-96ca-422b7d317db6_18/source/supabase/functions/create-payment-intent/index.ts","ezbr_sha256":"331865002f8f90749c9acd68d5ceb3311dd491bde2d46688c62e8ccd3b90a6af","files":[{"name":"functions/create-payment-intent/index.ts","content":"import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import Stripe from 'npm:stripe@^14.0.0'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.39.0'
import { checkRateLimit } from '../_shared/rateLimit.ts'
import { requireAuth } from '../_shared/auth.ts'
import { assertPositiveInt, assertOneOf, assertUUID, ValidationError } from '../_shared/validate.ts'
import { corsHeaders, handleCors } from '../_shared/cors.ts'

const stripe = new Stripe(Deno.env.get('STRIPE_SECRET_KEY') as string, {
    apiVersion: '2022-11-15',
    httpClient: Stripe.createFetchHttpClient(),
})

serve(async (req) => {
    const corsResponse = handleCors(req);
    if (corsResponse) return corsResponse;

    try {
        const { user } = await requireAuth(req)

        let { amount, captureMethod, metadata } = await req.json()
        let destination = null;
        let application_fee_amount = null;

        // ── Input validation ──
        amount = assertPositiveInt(amount, 'amount', 99999900)
        if (amount < 50) {
            throw new ValidationError(`Le montant minimum est de 0.50€ (reçu: ${(amount / 100).toFixed(2)}€)`)
        }
        if (captureMethod !== undefined && captureMethod !== null) {
            captureMethod = assertOneOf(captureMethod, 'captureMethod', ['automatic', 'manual'] as const)
        }
        if (metadata?.missionId) {
            metadata.missionId = assertUUID(metadata.missionId, 'metadata.missionId')
        }
        if (metadata?.emergencyId) {
            metadata.emergencyId = assertUUID(metadata.emergencyId, 'metadata.emergencyId')
        }
        if (metadata?.bidId) {
            metadata.bidId = assertUUID(metadata.bidId, 'metadata.bidId')
        }
        if (metadata?.quoteId) {
            metadata.quoteId = assertUUID(metadata.quoteId, 'metadata.quoteId')
        }
        if (metadata?.interventionId) {
            metadata.interventionId = assertUUID(metadata.interventionId, 'metadata.interventionId')
        }

        // Setup supabase to fetch the Connect Account ID securely
        const supabaseUrl = Deno.env.get('SUPABASE_URL')
        const supabaseKey = Deno.env.get('SUPABASE_ANON_KEY')

        // Rate limiting: 5 payment intents per minute per user
        await checkRateLimit(user.id, 'create_payment_intent', 5, 60_000)

        if (supabaseUrl && supabaseKey) {
            const supabase = createClient(supabaseUrl, supabaseKey, {
                global: { headers: { Authorization: req.headers.get('Authorization')! } }
            });

            let targetProviderId = null;

            if (metadata?.interventionId) {
                const { data: intervention } = await supabase.from('interventions').select('assigned_provider_id').eq('id', metadata.interventionId).single();
                if (intervention?.assigned_provider_id) targetProviderId = intervention.assigned_provider_id;
            } else if (metadata?.missionId) {
                const { data: mission } = await supabase.from('missions').select('assigned_provider_id').eq('id', metadata.missionId).single();
                if (mission?.assigned_provider_id) targetProviderId = mission.assigned_provider_id;
            } else if (metadata?.bidId) {
                const { data: bid } = await supabase.from('emergency_bids').select('provider_id').eq('id', metadata.bidId).single();
                if (bid?.provider_id) targetProviderId = bid.provider_id;
            } else if (metadata?.quoteId) {
                const { data: quote } = await supabase.from('mission_quotes').select('provider_id').eq('id', metadata.quoteId).single();
                if (quote?.provider_id) targetProviderId = quote.provider_id;
            } else if (metadata?.emergencyId) {
                const { data: emergency } = await supabase.from('emergency_requests').select('accepted_provider_id').eq('id', metadata.emergencyId).single();
                if (emergency?.accepted_provider_id) targetProviderId = emergency.accepted_provider_id;
            }

            if (targetProviderId) {
                const { data: profile } = await supabase.from('provider_profiles').select('stripe_account_id').eq('provider_id', targetProviderId).single();
                if (profile?.stripe_account_id) {
                    destination = profile.stripe_account_id;
                    // Altio 10%+10% commission model:
                    // - Owner pays: providerRate * 1.10 (amount already includes 10% service fee)
                    // - Provider receives: providerRate * 0.90 (providerRate minus 10% commission)
                    // - Altio keeps: amount - providerRate * 0.90 = amount * 2/11 ≈ 18.18% of total
                    //   (= 10% service fee from owner + 10% commission from provider)
                    application_fee_amount = Math.round(amount * 2 / 11);
                } else {
                    console.warn('[create-payment-intent] Provider has no Stripe account, manual transfer required')
                    metadata = { ...metadata, needs_manual_transfer: 'true' }
                }
            }
        }

        const intentParams: Stripe.PaymentIntentCreateParams = {
            amount: Math.round(amount),
            currency: 'eur',
            capture_method: captureMethod || 'automatic',
            metadata: metadata || {},
        };

        if (destination) {
            // Verify the Connect account exists and is usable before adding transfer_data
            try {
                const account = await stripe.accounts.retrieve(destination)
                if (account.charges_enabled) {
                    intentParams.transfer_data = {
                        destination: destination,
                    };
                    if (application_fee_amount) {
                        intentParams.application_fee_amount = application_fee_amount;
                    }
                } else {
                    console.warn('[create-payment-intent] Connect account has charges_enabled=false, creating payment without transfer')
                    intentParams.metadata = { ...intentParams.metadata, needs_manual_transfer: 'true' }
                }
            } catch (_stripeErr: unknown) {
                console.warn('[create-payment-intent] Could not verify Connect account, creating payment without transfer')
                intentParams.metadata = { ...intentParams.metadata, needs_manual_transfer: 'true' }
            }
        }

        const paymentIntent = await stripe.paymentIntents.create(intentParams)

        return new Response(
            JSON.stringify({
                clientSecret: paymentIntent.client_secret,
                paymentIntentId: paymentIntent.id
            }),
            {
                headers: { ...corsHeaders, 'Content-Type': 'application/json' },
                status: 200,
            }
        )
    } catch (error: unknown) {
        if (error instanceof ValidationError) {
            return new Response(JSON.stringify({ error: error.message }), {
                headers: { ...corsHeaders, 'Content-Type': 'application/json' },
                status: 400,
            })
        }
        const errMsg = error instanceof Error ? error.message : String(error)
        const isAuthError = errMsg.includes('authorization') || errMsg.includes('token')
        if (isAuthError) {
            return new Response(JSON.stringify({ error: errMsg }), {
                headers: { ...corsHeaders, 'Content-Type': 'application/json' },
                status: 401,
            })
        }
        const stripeError = error as { message?: string; type?: string; code?: string }
        console.error('create-payment-intent error:', stripeError.message, stripeError.type || '', stripeError.code || '')
        const message = stripeError.type === 'StripeInvalidRequestError'
            ? `Erreur Stripe: ${stripeError.message}`
            : stripeError.message || 'Erreur inconnue'
        return new Response(JSON.stringify({ error: message }), {
            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
            status: 400,
        })
    }
})
"},{"name":"functions/_shared/rateLimit.ts","content":"import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

/**
 * Simple DB-based rate limiter for Supabase Edge Functions.
 * Uses the rate_limit_log table (created in Sprint 6 migration).
 *
 * @param userId  - ID of the calling user
 * @param action  - Identifier for the action (e.g. 'create_payment_intent')
 * @param max     - Max requests allowed in the time window
 * @param windowMs - Time window in ms (default: 60 000 = 1 minute)
 */
export async function checkRateLimit(
  userId: string,
  action: string,
  max = 10,
  windowMs = 60_000,
): Promise<void> {
  const supabaseUrl = Deno.env.get('SUPABASE_URL') as string
  const serviceKey  = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') as string
  const db = createClient(supabaseUrl, serviceKey)

  const since = new Date(Date.now() - windowMs).toISOString()

  const { count, error } = await db
    .from('rate_limit_log')
    .select('*', { count: 'exact', head: true })
    .eq('user_id', userId)
    .eq('action', action)
    .gte('created_at', since)

  if (error) {
    // Non-blocking: if we can't check, let the request through
    console.warn('[rateLimit] Could not check rate limit:', error.message)
    return
  }

  if (count !== null && count >= max) {
    throw new Error(`Rate limit exceeded (${max} requests/${windowMs / 1000}s). Réessayez dans quelques instants.`)
  }

  // Log this request
  try {
    await db.from('rate_limit_log').insert({ user_id: userId, action });
  } catch (e: unknown) {
    console.warn('[rateLimit] Insert failed:', e instanceof Error ? e.message : String(e));
  }
}
"},{"name":"functions/_shared/auth.ts","content":"import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import type { User } from 'https://esm.sh/@supabase/supabase-js@2'

export type AuthResult = {
  user: User | null
  isServiceCall: boolean
  token?: string
}

/**
 * Validates the JWT from the Authorization header.
 * Throws if the token is missing or invalid.
 */
export async function requireAuth(req: Request): Promise<{ user: User; token: string }> {
  const authHeader = req.headers.get('Authorization') || req.headers.get('authorization')
  if (!authHeader) {
    throw new Error('Missing authorization header')
  }

  const token = authHeader.replace('Bearer ', '')

  const supabaseUrl = Deno.env.get('SUPABASE_URL') as string
  const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') as string

  // Utiliser service_role_key pour valider le token — c'est le pattern recommandé
  // pour les Edge Functions Supabase (le anonKey + global headers ne marche pas en Deno)
  const supabase = createClient(supabaseUrl, supabaseServiceKey)

  const { data: { user }, error } = await supabase.auth.getUser(token)

  if (error || !user) {
    console.error('[auth] getUser failed:', error?.message, '| token length:', token.length)
    throw new Error('Invalid or expired token')
  }

  console.log('[auth] User authenticated:', user.id)
  return { user, token }
}

/**
 * Accepts either an internal service key (x-service-key header)
 * or a valid user JWT. Useful for functions called by users AND
 * by other Edge Functions.
 */
export async function requireAuthOrServiceKey(req: Request): Promise<AuthResult> {
  // Méthode 1 : header x-service-key custom
  const serviceKey = req.headers.get('x-service-key')
  const internalKey = Deno.env.get('INTERNAL_SERVICE_KEY')
  if (internalKey && serviceKey === internalKey) {
    console.log('[auth] Service call authenticated via x-service-key')
    return { user: null, isServiceCall: true }
  }

  // Méthode 2 : le token Authorization EST la service_role_key
  // (cas où une Edge Function appelle une autre via db.functions.invoke)
  const authHeader = req.headers.get('Authorization') || req.headers.get('authorization')
  if (authHeader) {
    const token = authHeader.replace('Bearer ', '')
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')
    if (supabaseServiceKey && token === supabaseServiceKey) {
      console.log('[auth] Service call authenticated via service_role_key')
      return { user: null, isServiceCall: true }
    }
  }

  // Méthode 3 : JWT utilisateur classique
  const { user, token } = await requireAuth(req)
  return { user, isServiceCall: false, token }
}
"},{"name":"functions/_shared/validate.ts","content":"export class ValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ValidationError';
  }
}

export function assertString(val: unknown, field: string): string {
  if (typeof val !== 'string' || val.trim().length === 0) {
    throw new ValidationError(`${field} must be a non-empty string`);
  }
  return val.trim();
}

export function assertUUID(val: unknown, field: string): string {
  const s = assertString(val, field);
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s)) {
    throw new ValidationError(`${field} must be a valid UUID`);
  }
  return s;
}

export function assertPositiveInt(val: unknown, field: string, max = 99999900): number {
  const n = typeof val === 'string' ? parseInt(val, 10) : val;
  if (typeof n !== 'number' || !Number.isInteger(n) || n <= 0 || n > max) {
    throw new ValidationError(`${field} must be a positive integer (max ${max})`);
  }
  return n;
}

export function assertOneOf<T extends string>(val: unknown, field: string, options: readonly T[]): T {
  const s = assertString(val, field);
  if (!options.includes(s as T)) {
    throw new ValidationError(`${field} must be one of: ${options.join(', ')}`);
  }
  return s as T;
}

export function assertOptionalString(val: unknown, field: string): string | undefined {
  if (val === undefined || val === null) return undefined;
  return assertString(val, field);
}
"},{"name":"functions/_shared/cors.ts","content":"const ALLOWED_ORIGIN = Deno.env.get('ALLOWED_ORIGIN') || 'https://altio.app';

export const corsHeaders: Record<string, string> = {
  'Access-Control-Allow-Origin': ALLOWED_ORIGIN,
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

export function handleCors(req: Request): Response | null {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }
  return null;
}
